public void compareTraversals(List<List<Integer>> adj, int start) {
    Queue<Integer> queue = new LinkedList<>();
    queue.add(start);
    while (!queue.isEmpty()) {
        int node = queue.poll();
        for (int next : adj.get(node)) {
            if (!bfsSeen[next]) {
                queue.add(next);
            }
        }
    }

    Deque<Integer> stack = new ArrayDeque<>();
    stack.push(start);
    while (!stack.isEmpty()) {
        int node = stack.pop();
        for (int next : reverse(adj.get(node))) {
            if (!dfsSeen[next]) {
                stack.push(next);
            }
        }
    }
}
